const bankTexts = {"en": {"label": "MIDI OUT Bank - CC Saving Test", "short": "Saves CC assignments and step locks. All mods retained. Hardware test pending.", "desc": "CC saving test: Save Project now stores B-side gray-knob CC assignments and base values, plus per-step CC number/value locks with their MIDI patterns. Save, reload, then power-cycle and reload the project to verify them on hardware. Existing and new project slots are supported. Older projects without CC records start with unassigned knobs and empty CC locks. MIDI note/timing/live recording and LFO saving remain included. CC records use separate verified alternating copies; a CC error is reported separately and does not close B-side or invalidate the saved MIDI notes. All selectable mods, including ACID, MACRO and Model-TG, are retained through compatible compression. CC slides and all earlier B-side controls remain included. Hold SETTINGS and turn a gray knob to assign CC0–127/OFF; release SETTINGS and turn to send its value. Hold a TRIG and turn an assigned knob to lock it. FUNC + TRIG creates a trigless step. SETTINGS + TRIG toggles Slide on/off. SETTINGS + TRACK scrambles assigned CCs. LFO destinations use DATA to edit/confirm, BACK to cancel, and browse OFF then CC0–127 in a five-character scrolling window. CC persistence is verified in emulation and awaits hardware testing. Explicit Save Project is required; no automatic CC checkpointing yet."}, "fr": {"label": "Banque MIDI OUT - Test sauvegarde CC", "short": "Sauvegarde assignations et locks CC. Tous les mods conservés. Test matériel attendu.", "desc": "Test sauvegarde CC : Save Project conserve désormais assignations CC et valeurs de base des potards gris B, ainsi que numéro/valeur des locks CC par pas avec les patterns MIDI. Sauvegardez, rechargez puis redémarrez et rechargez le projet pour vérifier sur matériel. Slots existants et nouveaux acceptés. Projets anciens sans fichiers CC : potards non assignés, locks CC vides. Notes, timing, live-rec et sauvegarde LFO conservés. Copies CC alternées séparées et vérifiées ; erreur CC distincte sans fermer B ni invalider les notes sauvegardées. Tous les mods, ACID, MACRO et Model-TG compris, sont conservés par compression compatible. Slides CC et commandes B précédentes conservés. SETTINGS + potard gris choisit CC0–127/OFF ; relâchez puis tournez pour transmettre. TRIG maintenu + potard assigné verrouille le CC. FUNC + TRIG crée un trig de paramètres. SETTINGS + TRIG bascule Slide on/off. SETTINGS + TRACK randomise les CC assignés. Destinations LFO : DATA édite/confirme, BACK annule, ordre OFF puis CC0–127 et fenêtre défilante de cinq caractères. Persistance CC vérifiée en émulation, à tester sur matériel. Save Project explicite requis ; pas encore de sauvegarde CC automatique."}};
const bankFeature = {
 "id": "midi-bank-bundle",
 "cat": "seq",
 "status": "experimental",
 "label": "MIDI OUT Bank",
 "desc": "Test de sauvegarde MIDI et restauration au démarrage. Save Project écrit et vérifie les séquences B. Démarrage ou chargement d’un autre projet sauvegardé restaure ses séquences en arrière-plan. Attendre avant édition ou sauvegarde. Si le slot ne peut pas être associé, B reste accessible en RAM seule et les sauvegardes disque sont bloquées. Pas d’autosave des éditions. Écriture vérifiée sur matériel ; restauration après extinction à tester. Fichiers séparés hors backups Elektron. Sélections existantes, Model-TG et potard SPEED LFO2 conservés. Live-rec B inclus : RECORD + PLAY, puis PLAY avec RECORD maintenu pour changer la quantification. Save conserve notes, vélocité, durées en pas et retards au 1/64 de pas. Lit MBK2/MBK3, écrit MBK4 ; les anciennes versions ne lisent pas MBK4. Intégration live-rec/sauvegarde à tester sur matériel.",
 "requires": "model-tg",
 "credit": {
  "kind": "based",
  "who": "TinyGregAudio",
  "repo": "TinyGregAudio/Model-TG"
 },
 "license": "LICENSE-Model-TG",
 "variants": [
  {
   "id": "midi-bank-bundle",
   "label": null
  }
 ],
 "excludes": []
};
for (const key of ["label", "short", "desc"]) Object.defineProperty(bankFeature, key, {
  get: () => (bankTexts[document.documentElement.lang] || bankTexts.en)[key], configurable: true
});
window.MC_TWEAKS.features.push(bankFeature);
